import{_ as a,o as e,c as s,a2 as n}from"./chunks/framework.mRCPFc5l.js";const b=JSON.parse('{"title":"如何阅读本知识库","description":"","frontmatter":{},"headers":[],"relativePath":"about/how-to-read.md","filePath":"about/how-to-read.md","lastUpdated":1787216633000}'),o={name:"about/how-to-read.md"};function d(l,t,r,i,p,c){return e(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="如何阅读本知识库" tabindex="-1">如何阅读本知识库 <a class="header-anchor" href="#如何阅读本知识库" aria-label="Permalink to &quot;如何阅读本知识库&quot;">​</a></h1><blockquote><p>本站的“强验证”原则优先于完整性：没有可追溯证据时，正确答案是“不确定”，而不是补全一个看似合理的结论。</p></blockquote><h2 id="证据等级" tabindex="-1">证据等级 <a class="header-anchor" href="#证据等级" aria-label="Permalink to &quot;证据等级&quot;">​</a></h2><p>每个实践条目都应使用以下标签之一：</p><table tabindex="0"><thead><tr><th>标签</th><th>含义</th><th>AI 可以如何表述</th></tr></thead><tbody><tr><td><code>仓库事实</code></td><td>可在当前仓库源码、配置、发布物或正式记录中直接找到</td><td>“仓库目前明确记录……”</td></tr><tr><td><code>设计建议</code></td><td>工程上合理的方案，但没有 WheelOS 实验结果</td><td>“可以尝试……尚未证明……”</td></tr><tr><td><code>已验证</code></td><td>给出环境、步骤和结果，可由他人复现</td><td>“在指定条件下已验证……”</td></tr><tr><td><code>部分验证</code></td><td>只覆盖仿真、单模块或有限场景</td><td>“在有限条件下有效，不能外推到……”</td></tr><tr><td><code>待验证</code></td><td>假设、问题或缺少关键数据</td><td>“目前无法判断，需要……”</td></tr></tbody></table><h2 id="ai-回答的最小格式" tabindex="-1">AI 回答的最小格式 <a class="header-anchor" href="#ai-回答的最小格式" aria-label="Permalink to &quot;AI 回答的最小格式&quot;">​</a></h2><p>回答自动驾驶工程问题时，优先输出：</p><ol><li><strong>判断</strong>：已知、未知，还是需要实验。</li><li><strong>最可能的原因</strong>：按证据和排查成本排序。</li><li><strong>需要的数据</strong>：日志字段、时间范围、坐标系、硬件和版本。</li><li><strong>实验步骤</strong>：一次只改变一个关键变量。</li><li><strong>验收指标</strong>：用数值或可观察条件定义成功。</li><li><strong>边界</strong>：哪些场景、硬件或版本不适用。</li><li><strong>引用</strong>：链接到本知识库的具体页面或仓库文件。</li></ol><p>严禁把没有实验数据的建议写成“WheelOS 已支持”，也不要用“理论上可行”替代实车安全结论。</p><h2 id="引用规则" tabindex="-1">引用规则 <a class="header-anchor" href="#引用规则" aria-label="Permalink to &quot;引用规则&quot;">​</a></h2><p>引用时优先使用具体页面和证据 ID，而不是只引用首页。引用必须保留原文的状态、测试环境和限制条件。<code>llms.txt</code> 是导航，不是验证证明；<code>evidence/registry.json</code> 是验证记录索引，实践正文才是证据细节。</p><h2 id="如何提交一条新知识" tabindex="-1">如何提交一条新知识 <a class="header-anchor" href="#如何提交一条新知识" aria-label="Permalink to &quot;如何提交一条新知识&quot;">​</a></h2><p>请优先提交一个完整的问题记录，而不是孤立的结论：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>问题：可观察的现象</span></span>
<span class="line"><span>环境：软件版本、硬件、车辆/仿真、数据集</span></span>
<span class="line"><span>输入：话题、频率、时间戳、坐标系、配置</span></span>
<span class="line"><span>尝试：具体命令或改动</span></span>
<span class="line"><span>结果：日志、指标、截图或回放链接</span></span>
<span class="line"><span>结论：有效/无效/部分有效</span></span>
<span class="line"><span>边界：尚未覆盖的情况</span></span>
<span class="line"><span>证据：代码、提交、数据或实验记录</span></span></code></pre></div>`,14)])])}const u=a(o,[["render",d]]);export{b as __pageData,u as default};
